  {
    "sys_consequence_reasoning": "Five people against nothing.",
    "pda_other_regret_expectation": "I think that person would regret the hesitation"
  },
  {
    "sys_consequence_reasoning": "alternative is standing still while five workers get hit",
    "pda_other_regret_expectation": "I suspect they'll regret that for a long time"
  },
  {
    "sys_consequence_reasoning": "an empty siding versus five lives.",
    "pda_other_regret_expectation": "I'd guess they'd regret leaving"
  },
  {
    "ce_understood_harm": "Doing nothing means five people",
    "sys_consequence_reasoning": "Pulling means a train bumps a barrier. I can't find a cost.",
    "pda_other_regret_expectation": "I don't think they'd regret being on that track."
  },
  {
    "sys_consequence_reasoning": "Nobody gets hurt that way, and five people get hurt the other way.",
    "pda_other_regret_expectation": "I think they'd look back with regret"
  },
  {
    "sys_consequence_reasoning": "Leaving it means five workers hit.",
    "pda_other_regret_expectation": "would probably wrestle with regret for a while"
  },
  {
    "ce_understood_harm": "brother froze once during a road accident, and he's regretted it",
    "pda_other_regret_expectation": "would likely end up carrying the same weight"
  },
  {
    "sys_consequence_reasoning": "Five people's lives, weighed against a train with no one aboard",
    "pda_other_regret_expectation": "might regret the timing later"
  },
  {
    "sys_consequence_reasoning": "Staying still has a cost measured in people, and moving has no cost",
    "pda_other_regret_expectation": "Someone who stayed out of it... would deeply regret that"
  },
  {
    "sys_consequence_reasoning": "The siding is empty... so I pull it.",
    "pda_other_regret_expectation": "I doubt the workers would ever regret"
  }
